pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address unauthorized = address(0xdead);
    address recipient = address(0xbeef);

    function setUp() public { c = new EBU(); }

    function testRegression_property() public {
        address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address caddress = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        vm.deal(caddress, 10 ether);

        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory values = new uint[](1);
        values[0] = 1;

        vm.prank(unauthorized);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", tos, values));

        assertTrue(!ok, "Unauthorized caller should cause revert");
    }
}
